// studio_off_led.ino — ESP32-S3: выключение всех ПК + индикация на встроенном RGB
#include <WiFi.h>
#include <WiFiUdp.h>

// ===== Сети: обходятся все по очереди при каждом нажатии =====
const char* WIFI_SSIDS[] = { "DIR-615T-0DBC", "KIBERone", "KIBERone5" };
const char* WIFI_PASSS[] = { "23233010", "KIBERone", "KIBERone" };
const int   NET_COUNT = 3;

const int   UDP_PORT  = 8085;
const char* SECRET    = "STUDIO-OFF-7788";
const int   BUTTON    = 0;
const int   WAIT_MS   = 15000;

// ===== Встроенный RGB-светодиод (WS2812) =====
// Большинство плат: GPIO48. Если не горит — поменяй на 38.
const int LED_PIN = 48;

// цвета (R, G, B)
void setLed(int r, int g, int b) {
  neopixelWrite(LED_PIN, r, g, b);
}
void setLedOff() { setLed(0, 0, 0); }

WiFiUdp udp;

// краткое мигание: подтвердить событие
void blink(int r, int g, int b, int times, int ms) {
  for (int i = 0; i < times; i++) {
    setLed(r, g, b); delay(ms);
    setLedOff();     delay(ms);
  }
}

bool connectTo(int idx) {
  Serial.print("Switching to: "); // Serial оставлен только для отладки, можно убрать
  Serial.println(WIFI_SSIDS[idx]);

  WiFi.mode(WIFI_STA);
  WiFi.disconnect(false);
  WiFi.begin(WIFI_SSIDS[idx], WIFI_PASSS[idx]);

  for (int t = 0; t < WAIT_MS / 500; t++) {
    if (WiFi.status() == WL_CONNECTED) {
      setLed(0, 40, 0);      // зелёный — подключились
      return true;
    }
    setLed(40, 40, 0);       // жёлтый мигаем — ждём
    delay(250);
    setLedOff();
    delay(250);
  }
  return false;
}

void broadcastInCurrentNet() {
  setLed(0, 0, 60);          // синий — рассылка
  for (int i = 0; i < 2; i++) {
    udp.beginPacket(IPAddress(255, 255, 255, 255), UDP_PORT);
    udp.print(SECRET);
    udp.endPacket();
    delay(100);
  }
}

void setup() {
  pinMode(BUTTON, INPUT_PULLUP);
  udp.begin(UDP_PORT);

  setLed(40, 40, 0);         // жёлтый — стартуем
  if (!connectTo(0)) {
    setLed(60, 0, 0);        // красный — стартовая сеть недоступна
  }
}

void loop() {
  if (digitalRead(BUTTON) == LOW) {
    delay(50); // антидребезг
    if (digitalRead(BUTTON) == LOW) {
      int ok = 0;
      for (int i = 0; i < NET_COUNT; i++) {
        if (connectTo(i)) {
          broadcastInCurrentNet();
          ok++;
        }
      }
      // итог: сколько сетей накрыли — мигаем столько раз зелёным
      if (ok > 0) blink(0, 60, 0, ok, 300);
      else        blink(60, 0, 0, 3, 300); // красный — ни одна сеть не взялась
      // возвращаемся на основную сеть
      connectTo(0);
      while (digitalRead(BUTTON) == LOW) delay(10);
    }
  }
  // связь пропала в фоне — красный сигнал и тихо reconnect
  if (WiFi.status() != WL_CONNECTED) {
    setLed(60, 0, 0);
    connectTo(0);
  }
  delay(20);
}
